    # Find vertically separated bands of rows containing non-background cells.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # When two matching bands have different horizontal extents, copy the
    # extra foreground pattern from the wider band into the shorter one.
    for a in range(len(bands)):
        for b in range(a + 1, len(bands)):
            s1, e1 = bands[a]
            s2, e2 = bands[b]
            if e1 - s1 != e2 - s2:
                continue

            def extent(s, e):
                return max(c for row in grid[s:e]
                           for c, v in enumerate(row) if v != bg)

            x1, x2 = extent(s1, e1), extent(s2, e2)
            if x1 == x2:
                continue
            if x1 > x2:
                donor, target = (s1, e1), (s2, e2)
            else:
